const lastTicket = minutesOf(slots.firstEndTime) - slots.lastTicketMinutes;
const lastTicketDay = slots.firstDay;
for (const day of ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]) {
  if (day === slots.firstDay) { continue; }
  const ticket = minutesOf(slots.secondTime) + slots.lastTicketMinutes;
  if (ticket > lastTicket) { lastTicketDay = day; }
}
const successful = slots.askedDay === slots.firstDay
  ? "Friday " + slots.askedTime + " succeeds."
  : slots.availableDay === slots.firstDay
    ? slots.availableDay + " " + slots.availableTime + " succeeds."
    : "Neither " + slots.askedDay + " " + slots.askedTime + " nor " + slots.availableDay + " " + slots.availableTime + " succeeds.";
return successful;

