@answer jsEval
const slots = $slots;
const format = (hundredths) => Math.trunc(hundredths / 100) + "." + String(hundredths % 100).padStart(2, "0");
const useful = slots.throughput * (100 - slots.overheadPercent) * slots.minutes / 60;
probe(useful > 0, "the overhead must leave a positive useful output");
const rateHundredths = useful / slots.minutes;
const rate = Math.trunc(rateHundredths / 100) + "." + String(rateHundredths % 100).padStart(2, "0");
return "The useful output is " + format(useful) + " cases, which is " + rate + " cases per hour.";

